CREATE TABLE zone (
    zone_id         BIGINT PRIMARY KEY,
    source_system   TEXT NOT NULL,
    zone_name       TEXT NOT NULL
);
CREATE TABLE driver (
    driver_id               BIGINT PRIMARY KEY,
    source_system           TEXT NOT NULL,
    source_original_id      INT,
    driver_name             TEXT NOT NULL,
    joined_date             DATE NOT NULL,
    left_date               DATE,
