);
CREATE TABLE vehicle (
    vehicle_id          BIGINT PRIMARY KEY,
    source_system       TEXT NOT NULL,
    license_plate       TEXT NOT NULL,
    vehicle_make        TEXT NOT NULL,
    registration_year   SMALLINT NOT NULL,
    color               TEXT NOT NULL
);
CREATE TABLE customer (
    customer_id                 BIGINT PRIMARY KEY,
    source_system               TEXT NOT NULL,
    source_original_id          INT,
    name                        TEXT,
    phone                       TEXT,
    email                       TEXT,
    customer_type               TEXT NOT NULL,
    business_name               TEXT,
    merged_into_customer_id     BIGINT REFERENCES customer(customer_id),
    created_at                  DATE
);
CREATE TABLE driver_vehicle_assignment (
    assignment_id   BIGINT PRIMARY KEY,
    driver_id       BIGINT NOT NULL REFERENCES driver(driver_id),
    vehicle_id      BIGINT NOT NULL REFERENCES vehicle(vehicle_id),
    valid_from      DATE NOT NULL,
    valid_to        DATE
);
CREATE TABLE trip (
    trip_id             UUID PRIMARY KEY,
    source_system       TEXT NOT NULL,
    source_original_id  INT NOT NULL,
    rider_customer_id   BIGINT NOT NULL REFERENCES customer(customer_id),
