    vehicle_id          BIGINT NOT NULL REFERENCES vehicle(vehicle_id),
    pickup_zone_id      BIGINT NOT NULL REFERENCES zone(zone_id),
    dropoff_zone_id     BIGINT NOT NULL REFERENCES zone(zone_id),
    status              TEXT NOT NULL,
    requested_at        TIMESTAMP NOT NULL,
    delivered_at        TIMESTAMP,
    payment_method      TEXT NOT NULL,
    fare_amount         NUMERIC(10,2)
);
CREATE TABLE payment (
    payment_id              BIGINT PRIMARY KEY,
    service_type            TEXT NOT NULL,
    service_id              TEXT NOT NULL,
    amount                  NUMERIC(10,2) NOT NULL,
    status                  TEXT NOT NULL,
    payment_method          TEXT NOT NULL,
    payment_correction_flag BOOLEAN NOT NULL DEFAULT FALSE,
    attempted_at            TIMESTAMP NOT NULL
);
CREATE TABLE rating (
    rating_id       BIGINT PRIMARY KEY,
    source_system   TEXT NOT NULL,
    service_type    TEXT NOT NULL,
    service_id      TEXT NOT NULL,
    score           NUMERIC(4,1) NOT NULL,
    created_at      TIMESTAMP
);
CREATE TABLE product_launch (
    product_name    TEXT PRIMARY KEY,
    launch_date     DATE NOT NULL
);



